"""Explicit kernel representation differences shared by both package writers."""

from .input_storage import READONLY_SNAPSHOTS
from .memory_contract import (
    BUFFER_PROFILE,
    GUARDED_PROFILES,
    TENSOR_PROFILE,
    WORD_PROFILE,
)


def kernel_representation_differences(trace, *, dynamic=False):
    profile = trace.get("profile", TENSOR_PROFILE)
    differences = []
    if any(item.get("kind") == "native-verified-source-serialization" for item in trace.get("transformations", [])):
        differences.append("source-only generic serialization uses the pinned stock Triton library in an isolated worker before numeric or pointer normalization; complete source fields survive an exact native generic parse/print round trip, with original/output hashes, fixed MLIR printer flags and the actual native library identity recorded separately from the downstream shared optimizer; this requires the pin-probed Linux/Itanium MLIR printer-registration export and LLVM C API, with unavailable exports or failed verification refusing; no native object layouts cross the binding, public tensor/scalar ABI and receipt schemas are unchanged, and serialization grants no numerical, effect, alias or source-equivalence proof")
    byte_atomics = any("byte_view" in item for item in trace.get("memory", {}).get("atomic_payload", []))
    if byte_atomics:
        differences.append("explicit private-invocation typed byte-word atomics retain i8 owning storage and integer word values in one standard generic atomic region per active lane; original source-pointee byte addresses, whole-word bounds/alignment and per-byte ownership/initialization remain executable; source-word v2 bindings separately declare actual byte captures and isolated word formals with one explicit byte order; a checked private literal probe and integer codecs preserve logical byte order; native materialization selects the checked pure-integer atomic-region feature through normal ownership/lifetime checks; the public tensor/scalar ABI and receipt schemas are unchanged; this supplies no external participants, physical pointer identity, floating numeric policy or accelerator qualification")
    if "typed_storage_transport" in trace:
        differences.append("explicit typed storage transport preserves public owning tensor dtypes/shapes while selected width-changing roots use private i8 storage with an appended static word-byte axis; standard integer bitcasts/shifts retain every incoming and returned word without floating conversion; original memory-event grouping remains recoverable; guard costs are derived per public result from byte capacity and independently checked by Merlin; whole-root transport is an executable correctness path whose aligned wide-memory optimization remains downstream; this supplies no byte-backed atomic, physical address identity or accelerator implementation")
    if any(record.get("kind") == "logical-byte-buffer-word-event" for record in trace.get("transformations", [])):
        differences.append("different-width views of declared i8 allocation roots use explicit logical byte order and signed i64 byte offsets: each original addptr retains its own source-pointee size after source integer arithmetic; ordinary word loads/stores become one guarded byte plane with standard integer pack/unpack, preserving whole-tile snapshots, inactive fill bits and byte-level overlap/initialization checks; original word width, tile, byte order and source grouping remain in provenance; this grants no physical pointer identity, typed-root byte reinterpretation, indivisible byte-backed atomic, synchronization or accelerator implementation; public tensor/scalar ABI and receipt schemas are unchanged")
    if trace.get("source_argument_binding", {}).get("schema") == "t2m.source-allocation-bindings.v1":
        if any(record.get("representation") == "typed-root-byte-view-v1"
               for record in trace["source_argument_binding"].get("bindings", [])):
            differences.append("explicit byte-order allocation bindings pass changed-width pointer/descriptor parameters from a typed owning root: wrapper origins are measured in that root's original elements before real source pointer casts, while source pointer advances and descriptor strides keep their original pointee units; the public root dtype/shape and original source capsule remain unchanged, and standard typed-root byte transport retains whole-root words; this grants no physical pointer identity, byte-backed atomic, synchronization or target implementation")
        if any(record.get("representation") == "byte-buffer-view-v1"
               for record in trace["source_argument_binding"].get("bindings", [])):
            differences.append("explicit byte-order allocation bindings may pass wide typed pointer/descriptor parameters from one declared i8 allocation root: origins remain byte offsets before real pointer casts, while original element strides remain in their source pointee units; source argument configuration/custody and public root dtype remain unchanged; default bindings still refuse different widths, and no typed-root packing, physical identity or byte-backed atomic permission is supplied")
        if any(record.get("representation") == "equal-width-word-view-v1"
               for record in trace["source_argument_binding"].get("bindings", [])):
            differences.append("explicit source allocation bindings admit equal-width byte-aligned scalar pointer views of one declared owning root: the wrapper applies origins in root element units and emits real TTIR pointer bitcasts before native inlining; each source event keeps the root's storage type with register word casts, one update state and unchanged bounds/ownership/lifetime checks; original source types and casts remain in provenance/source custody; this grants no different-width byte alias, physical address identity, sub-byte representation or atomic-policy permission")
        differences.append("the public allocation-state entry takes each root once and binds source pointer arguments through an executable TTIR call, with explicit element origins and scalar bindings; source.ttir is this bound program and includes the private input kernel body; source operations and pointer sharing remain executable before upstream inlining; each writable root is returned once with untouched state preserved; callers supply the declared root ABI and unrelated writable input overlap still refuses")
        capsule_schema = trace["source_argument_binding"].get("source_capsule", {}).get("schema")
        if capsule_schema in ("t2m.source-allocation-capsule.v1", "t2m.source-allocation-capsule.v2"):
            differences.append("the portable allocation source capsule retains exact original and generic pre-wrapper source, the complete original argument roster, source-only native stage custody and optional normalized source/intake inventory; compiler staging independently validates byte links while excluding evaluator data; these records grant byte custody only, not source equivalence, numerical/effect, alias or target admission; older readers refuse the additional explicit artifact roster")
            if capsule_schema == "t2m.source-allocation-capsule.v2":
                differences.append("source-allocation capsule v2 additionally retains complete native generic source and printer identity, the original typed operation graph and executable protected TTIR before allocation normalization; selected FP8/source-assembly contracts expand before native pointer/descriptor/dot passes; source-only auditing grants no wrapper ABI admission, and original-to-protected-to-normalized byte custody grants no numerical or source-equivalence proof; public tensor/scalar/model ABI and capture receipt schemas are unchanged; v1-only readers refuse this explicit protected artifact roster")
        else:
            differences.append("legacy allocation bindings retain original pre-wrapper source bytes only in conversion work; no portable original-source custody is claimed")
        if "descriptor_bindings" in trace["source_argument_binding"]:
            differences.append("original descriptor arguments bind declared allocation roots with nonzero signed element origins and actual logical fields after the official pre-layout expansion; shared writable descriptor/pointer views use one root state before inlining, and declared i32 shape/stride fields lift to i64 through executable signed extensions; ordinary original AST metadata parameters remain explicitly bound; original descriptors and normalization evidence remain distinct from the bound program; this supplies no device descriptor byte layout, physical identity, mixed-type alias permission or accelerator equivalence")
    if trace.get("memory", {}).get("input_preparation") == READONLY_SNAPSHOTS:
        differences.append("overlapping readonly tensor arguments are snapshotted as independent logical values before serialization, preserving dtype and every input word; aliased scalar carriers are loaded by value without changing tensor storage; physical pointer identity and volatile observations remain outside this profile; overlap between tensor arguments involving writable storage still requires an explicit alias/state interface and refuses before copying; serialized/compiler inputs gain no alias dependency or permission to discard guards, and the generic raw-MLIR executor keeps its independent-input requirement")
    if any(buffer.get("dtype") in ("f8E4M3FN", "f8E4M3FNUZ", "f8E5M2", "f8E5M2FNUZ")
           for buffer in trace.get("spec", {}).get("buffers", [])):
        differences.append("FP8 tensors retain their exact logical MLIR format; NumPy inputs/references carry raw uint8 words, decoded only for numeric comparisons through the optional ml-dtypes codec; one-byte storage supplies no numeric cast/overflow policy or by-value FP8 calling convention; exact byte claims require explicit word comparisons")
    if profile == BUFFER_PROFILE:
        differences.append("explicit mixed tensor/memref payload with archived semantic witness and memory continuation; the public tensor/scalar ABI is retained")
    if profile in GUARDED_PROFILES:
        differences.append("explicit guarded standard-memory payload with an independent runtime admission report; active bounds, read/write ownership, completed initialization and per-store lane uniqueness are executable; source-base gathers retain memory effects before optimization; grid-derived metadata cost is explicit; no pure tensor witness is asserted")
    if profile == WORD_PROFILE:
        differences.append("explicit source-word address policy retains source integer arithmetic before signed i64 pointer-offset accumulation; raw offset tensors replace structured pointer views; word-stage input/output evidence is retained")
        if trace.get("memory", {}).get("word_conversion") == "native-isolated-events-v2":
            differences.append("region-local memory uses isolated native event templates reinserted at original locations and arithmetic-only parent conversion; word-stage v2 archives intermediate IR and both actual native reports; typed event reconstruction is checked; tensor/scalar ABI is unchanged")
    transformations = trace.get("transformations", [])
    if any(record.get("kind") == "source-assembly-implementation" for record in transformations):
        differences.append("explicit optional source-assembly providers decode complete pure snippets into closed standard scalar arithmetic/math DAGs, lifted through parallel Linalg for tensor values; exact source strings/constraints, source IDs, provider distribution/file identities and specification contracts remain in provenance; physical instruction selection, opaque assembly and runtime provider calls are absent from the emitted payload; public tensor/scalar ABI and receipts are unchanged; source equivalence is limited to the named provider contract and qualified cases, with unsupported effects, packing and instructions remaining refused")
    if any(record.get("kind") == "ttir-elementwise-map" and record.get("packing_proof", {}).get("grouping") == "independent-of-register-layout"
           for record in transformations):
        differences.append("packed scalar arithmetic and structured control are exposed as parallel logical element computation only after typed SSA establishes identical slot-local functions independent of register grouping; lexical binders, conditions, carried/result order, captured producers and complete region bodies remain executable; original pack size, congruence evidence and equivalent source locations remain in provenance; no physical lane/register layout, new public ABI or caller proof annotation is assumed; coupled/asymmetric slots, packed memory and unretained control execution/termination require their own grouping/effect contracts")
    if trace.get("source_layout_specialization") is not None:
        if any(record.get("kind") == "ttir-elementwise-map" and record.get("memory") for record in transformations):
            differences.append("source-specialized packed reads invoke the complete scalar region once per logical group in parallel Linalg, retaining one group-value vector per returned scalar slot; isolated upstream source-word templates and guarded admission preserve original read positions, masks, fills, control and mutation snapshots; mixed-root pointer interfaces retain one scalar selector per packed slot and restore returned offsets/selectors before later reads; this adds no map-write, physical-address, final-GPU or target permission and changes no public ABI or receipt schema")
        differences.append("source-dependent packed maps use an explicit caller-selected initial TritonGPU layout specialization; the actual native pass and linear-layout APIs provide an invertible logical grouping, retained with exact specialized source and implementation identity; one complete scalar region runs per unmapped logical group and tensor coordinates are restored; source layout choices can change coupled/asymmetric math and are not consumer placement or optimization hints; no device binary, final optimized GPU correspondence or accelerator execution is claimed; public tensor/scalar ABI and receipt schemas are unchanged")
    if trace.get("descriptor_argument_binding", {}).get("schema") == "t2m.logical-descriptor-arguments.v1":
        differences.append("external tensor descriptor arguments use the official one-to-many logical field ABI: one owning allocation tensor, rank signed-i64 shapes, rank signed-i64 element strides, a NaN-padding bool and an f32-to-TF32 rounding bool; ordinary source arguments retain their order with expanded source positions explicit; shape fields require nonnegative input bounds, runtime allocation bounds/ownership remain checked, and flags drive the actual standard computation; this is not a device descriptor byte layout or physical pointer identity contract, and nonzero descriptor-base origins/shared writable descriptor roots still require explicit state bindings")
    if any(record.get("descriptor_profile", {}).get("name") == "logical-tensor-descriptors-v1"
           for record in transformations):
        differences.append("in-kernel tensor descriptors reuse Triton's pinned-version pre-layout pointer expansion: logical base/shape/element-strides, signed per-dimension bounds, source zero/NaN padding and store/reduction masks remain executable; indexed tiles and source reduction kind/order/scope are retained, with ordinary scatter uniqueness and private atomic effects checked by the selected memory profile; public inputs remain allocation tensors plus declared scalar bindings and writable allocations return complete state; no physical TMA descriptor ABI, async transport, alignment/placement mapping or accelerator equivalence is supplied; original and normalized source graphs remain distinct, and descriptor provenance grants no semantics")
    if any(step == "--math-expand-ops=ops=rsqrt" or isinstance(step, dict)
           and "--math-expand-ops=ops=rsqrt" in step.get("command", []) for step in trace.get("pipeline", [])):
        differences.append("the shared computation stage includes upstream's selected reciprocal-root expansion into sqrt/division; exact source-word pipeline custody requires a reader that admits this additional pass while retaining legacy evidence; unfiltered or different math expansions are not covered")
    if any(record.get("kind") == "source-external-standard-math" for record in transformations):
        differences.append("pure default libdevice functions use the explicit logical-libdevice-standard-math-v1 profile: checked symbol, arity, exact f32/f64 prototype and empty/custom-library boundaries precede the upstream standard math conversion; the two missing double tanh/atanh table entries have standard typed completions; original source IDs, caller intent and library declarations remain beside executable math; host libm accuracy, computed NaN class and gradual-underflow behavior do not assert bit identity to NVIDIA library approximations, floating-point environment effects or accelerator implementations; unknown/custom/impure external dependencies remain unqualified; public tensor/scalar ABI and package schemas are unchanged")
    if any(record.get("dot_precision", {}).get("input_precision") in ("bf16x3", "bf16x6")
           for record in trace.get("source_operations", [])):
        differences.append("f32 BF16x3/BF16x6 use the actual pinned-version Triton F32DotTC pass before layout or target compilation: typed BF16 residual splits, ordered partial contractions, correction-NaN clearing and the original C added after the composite remain executable; source and normalized graphs stay distinct, caller intent and original precision remain in the kernel source inventory annotation, and no per-operation original-source bijection is claimed; the selected host uses standard f32 products/ascending-K additions with gradual underflow, without asserting GPU Tensor Core rounding/FTZ or accelerator performance; the normalizer binary and normalized bytes are separately hash-bound, and the source reference revision is not a build receipt")
    if any("tf32_numeric_profile" in record for record in transformations):
        differences.append("TF32 uses the explicit logical-tf32-e8m10-rtz-v1 numeric profile: standard integer arithmetic quantizes dot inputs toward zero to ten fraction bits with gradual underflow and computed NaN class; TF32x3 reuses Triton's actual F32DotTC pass, expands only its generated nearest-ties-away conversion, and retains residual reuse, ordered partial contractions, correction-NaN clearing and original C after the composite; direct TF32 retains source C inside the contraction; original/normalized graphs and kernel-level caller intent remain separate; standard host f32 products/ascending-K additions do not assert equivalence to every GPU's implementation-defined TF32 representation, accumulator order, subnormal behavior or performance; public tensor/scalar storage and package schemas are unchanged")
    if any(record.get("kind") == "source-scaled-dot" for record in transformations):
        differences.append("scaled dots use the explicit logical-mx-f64-v1 internal-precision profile: packed logical tiles and per-group scales expand to standard parallel linalg, original C is extended before f64 contraction and the result rounds to its declared type; all finite E8M0 exponents including code zero are preserved and scale NaNs propagate even when fastMath permits their omission; physical MX instructions and GPU-specific intermediate rounding are not selected; ABI and package schema are unchanged")
    contracts = [record["dot_numeric"] for record in trace.get("normalized_operations",trace.get("source_operations",[])) if "dot_numeric" in record]
    if contracts:
        differences.append("typed named contractions retain original source C, source input formats, precision applicability and imprecise-accumulation bound in provenance; inputPrecision is semantically ignored for non-f32 inputs according to the pinned TTIR definition; selected native FP8 widening uses upstream named-op generalization before expanding scalar casts, including scalar fill transport; portable named matmul, tile reuse and runtime K loops remain intact; source constant negative zero is restored only from proved typed constant/bitcast facts and post-contraction adds remain separate; no GPU accumulator-order or accelerator performance claim is implied")
    if any(record.get("kind") == "source-fp8-conversion" for record in transformations):
        differences.append("FP8 conversion requires an explicit finite-overflow/infinity contract: ieee, satfinite or satfinite-nan-inf; standard clamps, selections and RTNE casts retain that contract, with exact backward comparison and word correction for RTZ and an exact f32 bridge for smaller or equal-width source formats; provenance preserves source intent without selecting semantics; the native host additionally selects Merlin's lower_fp8_narrowing before widening and BF16 legalization; logical FP8 tensor types, byte storage and ownership gates remain unchanged, and no accelerator implementation is implied")
    if any(record.get("source_policy_profile") == "t2m.per-cast-fp8.v1" for record in transformations):
        differences.append("t2m.per-cast-fp8.v1 explicitly selects each nonidentity TTIR-to-FP8 cast's t2m.fp8_overflow semantic StringAttr; all source casts validate and expand before helper inlining or folding; prov tags never supply numeric choices; this software source profile changes no public tensor ABI or receipt schema and does not establish an unspecified backend's conversion semantics")
    if any(record.get("kind") == "source-floating-conversion" for record in transformations):
        differences.append("explicit floating conversion composites retain source/target formats, rounding, original source IDs and caller intent; RTZ uses standard nearest casts with exact backward comparison and word correction, equal-width formats use an exact f32 bridge, and f64-to-16-bit RN uses a round-to-odd f32 bridge to avoid double rounding and missing direct runtime helpers; this is a standard MLIR expansion without GPU mapping, not permission for FP8 saturation or unsupported numeric policies")
    if any(record.get("opcode") == "tt.fp_to_fp" and
           any(name in type_ for name in ("f8E4M3FN", "f8E4M3FNUZ", "f8E5M2", "f8E5M2FNUZ")
               for type_ in record.get("input_types", []))
           for record in trace.get("normalized_operations", trace.get("source_operations", []))):
        differences.append("portable FP8 widening retains standard arith.extf and original source correspondence; the selected native host uses Merlin's explicit lower_fp8_widening feature to decode exact finite values, infinities and signed zeros through standard operations, preserving computed NaN class without selecting its payload; byte transport and ownership/lifetime checks remain separate; this supplies no FP8 narrowing/saturation, equal-width conversion or accelerator implementation")
    scalar_math = [record for record in trace.get("normalized_operations",trace.get("source_operations",[]))
        if record.get("opcode") in ("tt.clampf","tt.precise_divf","tt.precise_sqrt")]
    if scalar_math:
        differences.append("source clamp/precise-div/sqrt reuse upstream standard min/max, arith.divf and math.sqrt; source NaN mode, tensor types and dataflow remain in the payload and provenance; numeric qualification must distinguish defined values, signed-zero rules and unspecified computed NaN payloads; the normal nearest-even gradual-underflow host environment is explicit, with no alternate FP-environment or accelerator claim")
        if any("bf16" in type_ for record in scalar_math for type_ in (*record.get("input_types",[]),*record.get("output_types",[]))):
            differences.append("portable BF16 scalar math retains its source types; the selected host may require Merlin's explicit emulate_bfloat_elementwise feature, upstream scalar arithmetic emulation and BF16 rounding casts, followed by the unchanged word-transport feature; storage and public tensor ABI remain two-byte BF16")
    if any(t.get("kind") == "source-logical-print-events" for t in transformations):
        differences.append("source print events use standard vector.print and SCF value/control flow, once per logical program/operand/element in operand-row-major order; physical thread replicas/interleaving are abstracted; source prefixes are literal data; integer signedness, exact unsigned64 and raw floating/integer hex words remain executable; floating hex is an explicit original-typed-word software profile, without a GPU varargs byte-equivalence claim; the selected software profile uses six fixed decimal places, C numeric locale and Merlin's explicit lower_scalar_diagnostics feature; pointers need a separate logical-address contract and accelerator handling remains unqualified; public tensor/scalar/void ABI is unchanged")
    if any(t.get("kind") == "source-fail-stop-assertions" for t in transformations):
        differences.append("source assertions use upstream scalar/lane-wise standard cf.assert at original control positions, with source condition/message IDs retained; failing native invocations print literal diagnostics and abort using the evaluator's libc stdout/setbuf transport; the public tensor/scalar ABI is unchanged")
        if any("\x00" in assertion["message"] for t in transformations if t.get("kind") == "source-fail-stop-assertions"
                for assertion in t["assertions"]):
            differences.append("embedded NUL diagnostics require Merlin's explicit lower_length_aware_diagnostics native feature and T2M_MERLIN_ROOT for native verification; the complete UTF-8 literal plus linefeed uses an internal byte-counted putchar/abort expansion after ownership checks; portable cf.assert and public/package schemas are unchanged")
    if any(t.get("kind") == "logical-boolean-byte-memory" for t in transformations):
        differences.append("exclusive Triton Boolean byte loads observed by nonzero tests and stores of zero-extended i1 values become logical i1 tensor memory; masks, fills and original source IDs remain explicit; raw byte observations and changed byte addressing require a separate storage ABI")
    if any(t.get("kind") == "logical-pointer-word-view" for t in transformations):
        differences.append("equal-width logical pointer views retain original storage tensor types and source-word offsets; loads/stores use register bitcasts rather than physical aliases or whole-buffer representation copies; source integer fill bits are selected after a masked zero-filled storage load; word-view provenance is retained")
    if any(t.get("kind") == "logical-atomic-word-view" for t in transformations):
        differences.append("integer word atomics retain floating tensor storage and exact source integer updates in standard generic atomic regions: RMW on f32/f64 and CAS on f16/f32/f64; word-view dtypes and unchanged element address units are explicit v4 event/access/payload facts, while original primitive contracts remain shared across call contexts; exact legacy source-enriched records remain readable; old words are preserved with typed inactive zero refinement for masked RMW; the native ownership toolchain requires Merlin's checked atomic-word-view legalization and default 64-bit descriptor/index ABI; portable MLIR contains no physical alias or opaque helper")
    if any(p.get("operation") == "cas" and p.get("word_view") for p in trace.get("memory", {}).get("atomic_payload", [])):
        differences.append("word CAS uses an additive source-word stage v2 typed-template variant: input_types bind actual floating storage captures while template_input_types bind integer pointer formals only at the isolated native pointer-analysis boundary; producer replay reconstructs the complete typed event and consumer staging checks the declared pair; public tensors, artifact names and receipt schemas are unchanged; native CAS helpers return integer old words to avoid half floating ABI conversions")
    selected = [t for t in transformations if t.get("kind") == "selected-pointer-memory"]
    if selected:
        differences.append("finite mixed-base pointers use internal logical-buffer selectors paired with source-word offsets; predicated accesses stay at the original memory event; the public tensor/scalar ABI is unchanged")
        payload = trace.get("memory", {}).get("atomic_payload", [])
        viewed = {tuple(sorted(p["source_ids"])) for p in payload if p.get("word_view")}
        ordinary = {tuple(sorted(p["source_ids"])) for p in payload if not p.get("word_view")}
        if viewed & ordinary:
            differences.append("selected integer atomics retain each root's actual integer or equal-width floating storage type; one complete source context can bind both plain and word-view events; compiler staging matches their actual storage captures independently of logical CAS template formals, while primitive contracts and complete producer event reconstruction remain mandatory; stage/artifact schemas and public tensor/scalar ABI are unchanged")
        if any(t.get("expansion") == "per-root-original-storage-memory-event-with-register-bitcasts" for t in transformations):
            differences.append("selected ordinary memory retains each root's own equal-width storage dtype; predicated loads/stores perform register bitcasts at the original event and preserve source fills after loading; shared element offsets do not imply a shared storage representation; artifact and public tensor/scalar ABI schemas are unchanged")
        if any(t["missing_other_zero_refinement"] for t in selected):
            differences.append("inactive undefined source load values use the pinned upstream gather's zero refinement; this does not assert that inactive source memory was initialized or read")
    if any(t.get("kind") == "logical-selector-permutation" for t in transformations):
        differences.append("closed selector permutations retain immutable initial selector tiles and carry scalar i32 table indices through the original loop; logical per-lane choices are decoded at their uses, while original source-word offset recurrences remain executable; this changes internal control representation without a GPU mapping, new public argument or native lifetime exemption")
    if any("t2m-expand-cat-preserve-order" in t.get("pipeline", []) for t in transformations):
        differences.append("TTIR cat uses a checked pre-layout join/transpose/reshape expansion in lhs-then-rhs order, choosing a permitted ordering; original native source and normalized graphs remain distinct")
    if dynamic:
        differences.append("ABI v5 named runtime tensor dimensions and logical ceil-divided grids; dynamic result allocation uses scalar bindings; Merlin staging uses compile-signature v2")
    if trace.get("memory", {}).get("effect_profile") == "private-invocation-integer-atomics-v1":
        differences.append("explicit private-invocation integer atomics use standard memref RMW operations and original old values; v3 thirty-bit owner fragments permit atomic collisions while rejecting ordinary races; source scope/order are retained with stronger standard acq_rel semantics; inactive undefined old values refine to zero; tensor/scalar ABI is unchanged")
    if trace.get("memory", {}).get("effect_profile") == "private-invocation-typed-atomics-v2":
        differences.append("explicit private-invocation typed atomics retain integer RMW/CAS, bitwise f32/f64 exchange and IEEE f64 round-to-nearest-even addition with subnormals preserved and unspecified arithmetic NaN payloads; v4 memory admission retains v3 thirty-bit ownership, initialization and guard costs; floating exchange preserves all old/new bits without arithmetic or rounding; source scope/order use stronger standard acq_rel semantics; inactive undefined old values refine to typed zero; tensor/scalar ABI is unchanged")
    numeric = {event.get("numeric_contract") for event in trace.get("memory", {}).get("atomic_payload", [])}
    if "ieee-f64-rne-add-quiet-nans" in numeric:
        differences.append("strict IEEE f64 atomic addition preserves subnormals, round-to-nearest-even, exact old words and explicit arithmetic NaN quieting in standard generic atomic regions; the versioned quiet-nans contract distinguishes it from the legacy standard-addf profile, which does not guarantee NaN quieting after constant normalization; native ownership requires Merlin's checked atomic-word feature, complete internal CAS retry helper and default 64-bit descriptor/index ABI; core artifacts and tensor/scalar ABI are unchanged")
    if "f32-rne-sign-preserving-ftz-add" in numeric:
        differences.append("explicit f32 atomic addition policy flushes subnormal inputs/results to sign-preserving zero with round-to-nearest-even; arithmetic NaN payload/sign is unspecified and old words are exact; portable generic atomic regions contain the executable bit arithmetic; native ownership requires Merlin's checked atomic-word feature and default 64-bit descriptor/index ABI, preserving the complete internal CAS retry helper through lifetime checks; no native helper appears in portable MLIR")
    if "ieee-f32-rne-add" in numeric:
        differences.append("explicit IEEE f32 atomic addition policy preserves subnormal inputs/results with round-to-nearest-even, exact old words and unspecified arithmetic NaN payload/sign; portable generic atomic regions retain addition and explicit result NaN quieting through canonicalization; native ownership requires Merlin's checked atomic-word feature and complete internal CAS retry helper under the default 64-bit descriptor/index ABI; package artifacts and tensor/scalar ABI are unchanged")
    if any(item.get("operation") == "cas" for item in trace.get("memory", {}).get("atomic_payload", [])):
        differences.append("compare/exchange uses a standard generic atomic comparison/select region, retaining success/failure values and the original old word; selected bases branch inside parallel tiles; the pinned native ownership toolchain additionally requires Merlin's checked compare/exchange or atomic-word-view helper legalization and qualified default 64-bit descriptor/index ABI (T2M_MERLIN_ROOT for native qualification); portable model.mlir retains no LLVM operations or opaque helper calls")
    if byte_atomics:
        # Ordinary representation records describe their own permission only;
        # the separate typed event contract above supplies atomic admission.
        differences = [difference.replace("no byte-backed atomic,", "no independent atomic permission,")
                       .replace("indivisible byte-backed atomic,", "independent atomic permission,")
                       .replace(", byte-backed atomic,", ", independent atomic permission,")
                       .replace("no byte-backed atomic permission", "no independent atomic permission")
                       for difference in differences]
    return differences
